def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    marks = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    for r in range(h):
        cols = [c for rr, c in marks if rr == r]
        cols.sort()
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = sorted(r for r, cc in marks if cc == c)
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
